-- =====================================================================
-- SIGMA — data seed 3: Regional Performance Indicators (RPI)
--
-- Sumber: 20260810-Data_Modul_RPI.xlsx, sheet tbl_bscindicator_reg
-- 23 indikator, 135 baris nilai (indikator x tahun x region).
-- Region: Jawa, Sumatera-A, Sumatera-B, Kalimantan, dan Akumulasi Regional.
--
-- Baris 'Akumulasi Regional' hanya memuat TARGET dan catatan. Nilai Q1-Q4-nya
-- dikosongkan karena dihitung aplikasi sebagai penjumlahan kuartal keempat region.
--
-- MENGGANTI SELURUH DATA RPI: indikator bertipe RPI dihapus lebih dulu agar
-- indikator yang sudah tidak ada pada file sumber tidak tertinggal.
-- Data OPI dan PPI tidak tersentuh.
-- =====================================================================

-- Pastikan kolom region dan primary key sudah sesuai, apa pun urutan menjalankannya.
alter table public.indicator_years
  add column if not exists region text not null default 'National';

do $$ begin
  if exists (
    select 1 from pg_constraint
    where conname = 'indicator_years_pkey'
      and (select count(*) from unnest(conkey)) = 2
  ) then
    alter table public.indicator_years drop constraint indicator_years_pkey;
    alter table public.indicator_years
      add constraint indicator_years_pkey primary key (indicator_id, year, region);
  end if;
end $$;

delete from public.indicators where type = 'RPI';

on conflict (id) do update set
  type=excluded.type, name=excluded.name, unit=excluded.unit, calc=excluded.calc,
  t2030=excluded.t2030, strategy_map=excluded.strategy_map, outcome=excluded.outcome,
  accountability=excluded.accountability, program=excluded.program,
  details=excluded.details, portfolio=excluded.portfolio;

on conflict (indicator_id, year, region) do update set
  target = excluded.target, q1 = excluded.q1, q2 = excluded.q2,
  q3 = excluded.q3, q4 = excluded.q4, notes = excluded.notes;

select region, count(*) as baris,
       count(*) filter (where target is not null) as punya_target,
       count(*) filter (where coalesce(q1,q2,q3,q4) is not null) as punya_actual
from public.indicator_years where indicator_id like 'RPI-%'
group by region order by region;
